Lemma stk_shz_vis (H0 : word -> bool) (M : word -> option byte) t :
  (forall a n, (forall i, 0 <= i < n -> in_shadow_of (ahl_ceil ar) (ar_sptop ar - ahl_ceil ar) (a + i)) -> L5A.avis H0 a n) ->
